/**
 * KZGRevocation.test.js
 *
 * Runs the KZG revocation contract against the real EIP-2537 precompiles on
 * the in-process Hardhat network (hardfork "prague"). No pairing mock is used.
 *
 * Proofs come from test/fixtures/kzg_revocation.json, generated by
 * scripts/gen_kzg_fixtures.py with c-kzg and the EIP-4844 trusted setup.
 *
 * Run: npx hardhat test test/KZGRevocation.test.js
 */

const { expect } = require("chai");
const { ethers } = require("hardhat");
const fixtures = require("./fixtures/kzg_revocation.json");

const R = BigInt(fixtures.scalar_modulus);
const { empty, base, updated } = fixtures.sets;

// EIP-2537: 2-pair pairing check = 32,600 * 2 + 37,700. With the 21,000
// transaction base cost, no valid verification can use less than this.
const MIN_VERIFY_GAS = 21_000 + 102_900;

const opening = (set, z) => set.openings.find((o) => o.z === String(z));

/** Send verifyNonRevocation as a transaction; return the logged result and gas. */
async function verifyTx(contract, w, z, y) {
  const tx = await contract.verifyNonRevocation(w, z, y);
  const receipt = await tx.wait();
  const log = receipt.logs.map((l) => contract.interface.parseLog(l)).find((l) => l && l.name === "Verified");
  return { ok: log.args.ok, gas: Number(receipt.gasUsed) };
}

describe("KZGRevocation (EIP-2537 precompiles)", function () {
  let owner, other, rev, harness;

  beforeEach(async function () {
    [owner, other] = await ethers.getSigners();
    rev = await (await ethers.getContractFactory("KZGRevocation")).deploy(base.commitment);
    await rev.waitForDeployment();
    harness = await (await ethers.getContractFactory("KZGVerifierHarness")).deploy();
    await harness.waitForDeployment();
  });

  describe("fixtures", function () {
    it("every fixture proof verifies off-chain", function () {
      for (const set of [empty, base, updated]) {
        for (const o of set.openings) expect(o.offchain_verifies).to.equal(true);
      }
    });
  });

  describe("verifyNonRevocation", function () {
    it("1. accepts a valid proof for a non-revoked ID", async function () {
      for (const z of [5, 11, 12345]) {
        const o = opening(base, z);
        const { ok, gas } = await verifyTx(rev, o.w, o.z, o.y);
        expect(ok).to.equal(true);
        expect(gas).to.be.at.least(MIN_VERIFY_GAS);
        console.log(`    z=${z} valid non-revoked: ok=${ok} gas=${gas.toLocaleString()}`);
      }
    });

    it("2. rejects a revoked ID, whose honest opening has y = 0", async function () {
      for (const z of [3, 7, 9]) {
        const o = opening(base, z);
        expect(o.y).to.equal("0");
        const { ok, gas } = await verifyTx(rev, o.w, o.z, o.y);
        expect(ok).to.equal(false);
        console.log(`    z=${z} revoked (y=0): ok=${ok} gas=${gas.toLocaleString()}`);
      }
    });

    it("2b. rejects a revoked ID that claims a non-zero y", async function () {
      const o = opening(base, 3);
      for (const y of [1n, 16n, R - 1n]) {
        expect(await rev.checkNonRevocation(o.w, o.z, y)).to.equal(false);
      }
      // ... also with a witness borrowed from a valid opening
      const good = opening(base, 5);
      expect(await rev.checkNonRevocation(good.w, 3, good.y)).to.equal(false);
    });

    it("3. rejects a tampered witness", async function () {
      const o = opening(base, 5);
      // a valid curve point, but the witness for a different ID
      const wrongW = opening(base, 11).w;
      const { ok, gas } = await verifyTx(rev, wrongW, o.z, o.y);
      expect(ok).to.equal(false);
      console.log(`    tampered w (other point): ok=${ok} gas=${gas.toLocaleString()}`);

      // one flipped bit: no longer a curve point, so the precompile fails
      const bytes = ethers.getBytes(o.w);
      bytes[127] ^= 1;
      await expect(rev.verifyNonRevocation(ethers.hexlify(bytes), o.z, o.y))
        .to.be.revertedWithCustomError(rev, "PrecompileFailed");
    });

    it("4. rejects a wrong y", async function () {
      const o = opening(base, 5);
      const { ok, gas } = await verifyTx(rev, o.w, o.z, BigInt(o.y) + 1n);
      expect(ok).to.equal(false);
      console.log(`    wrong y: ok=${ok} gas=${gas.toLocaleString()}`);
    });

    it("5. rejects y = 0 for a non-revoked ID", async function () {
      const o = opening(base, 5);
      const { ok } = await verifyTx(rev, o.w, o.z, 0);
      expect(ok).to.equal(false);
    });

    it("6. reverts on non-canonical scalars (z >= r or y >= r)", async function () {
      const o = opening(base, 5);
      for (const [z, y] of [[R, BigInt(o.y)], [BigInt(o.z) + R, BigInt(o.y)], [BigInt(o.z), R], [BigInt(o.z), BigInt(o.y) + R]]) {
        await expect(rev.verifyNonRevocation(o.w, z, y)).to.be.revertedWithCustomError(rev, "NonCanonicalScalar");
      }
    });

    it("7. rejects a stale proof after the commitment is updated", async function () {
      // ID 11 is fine under `base`, then gets revoked in `updated`
      const stale = opening(base, 11);
      expect((await verifyTx(rev, stale.w, stale.z, stale.y)).ok).to.equal(true);

      await (await rev.updateCommitment(updated.commitment)).wait();

      expect((await verifyTx(rev, stale.w, stale.z, stale.y)).ok).to.equal(false);
      // a still-valid ID's old proof is stale too, and its fresh proof works
      const old5 = opening(base, 5);
      expect((await verifyTx(rev, old5.w, old5.z, old5.y)).ok).to.equal(false);
      const new5 = opening(updated, 5);
      expect((await verifyTx(rev, new5.w, new5.z, new5.y)).ok).to.equal(true);
      // the newly revoked ID now opens to zero
      const new11 = opening(updated, 11);
      expect(new11.y).to.equal("0");
      expect((await verifyTx(rev, new11.w, new11.z, new11.y)).ok).to.equal(false);
    });

    it("handles the empty revoked set (f = 1, witness at infinity)", async function () {
      const r0 = await (await ethers.getContractFactory("KZGRevocation")).deploy(empty.commitment);
      await r0.waitForDeployment();
      const o = opening(empty, 5);
      expect(o.y).to.equal("1");
      expect(BigInt(o.w)).to.equal(0n);
      expect((await verifyTx(r0, o.w, o.z, o.y)).ok).to.equal(true);
    });

    it("reverts on a witness of the wrong length", async function () {
      const o = opening(base, 5);
      await expect(rev.verifyNonRevocation(o.w_compressed, o.z, o.y))
        .to.be.revertedWithCustomError(rev, "BadPointLength");
    });

    it("checkNonRevocation (view) agrees with the transaction result", async function () {
      for (const o of base.openings) {
        const viewResult = await rev.checkNonRevocation(o.w, o.z, o.y);
        expect(viewResult).to.equal(!o.revoked);
        expect((await verifyTx(rev, o.w, o.z, o.y)).ok).to.equal(viewResult);
      }
    });
  });

  describe("updateCommitment", function () {
    it("is owner-only", async function () {
      await expect(rev.connect(other).updateCommitment(updated.commitment))
        .to.be.revertedWithCustomError(rev, "OnlyOwner");
    });

    it("stores the commitment and emits CommitmentUpdated", async function () {
      await expect(rev.updateCommitment(updated.commitment))
        .to.emit(rev, "CommitmentUpdated").withArgs(updated.commitment);
      expect(await rev.commitment()).to.equal(updated.commitment);
    });

    it("rejects a commitment that is not 128 bytes (e.g. the 48-byte compressed form)", async function () {
      await expect(rev.updateCommitment(updated.commitment_compressed))
        .to.be.revertedWithCustomError(rev, "BadCommitmentLength");
    });

    it("reports gas", async function () {
      const receipt = await (await rev.updateCommitment(updated.commitment)).wait();
      console.log(`    updateCommitment (128-byte C): gas=${Number(receipt.gasUsed).toLocaleString()}`);
    });
  });

  describe("KZGVerifier variants", function () {
    it("the G1-only form and the G2MSM form give the same answer", async function () {
      const o5 = opening(base, 5);
      const cases = [
        ...base.openings.map((o) => [base.commitment, o.w, o.z, o.y, true]),
        [base.commitment, o5.w, o5.z, BigInt(o5.y) + 1n, false],
        [base.commitment, opening(base, 11).w, o5.z, o5.y, false],
        [updated.commitment, o5.w, o5.z, o5.y, false],
        [empty.commitment, opening(empty, 5).w, 5, 1, true],
      ];
      for (const [c, w, z, y, expected] of cases) {
        expect(await harness.verify(c, w, z, y)).to.equal(expected);
        expect(await harness.verifyWithG2Msm(c, w, z, y)).to.equal(expected);
      }
    });

    it("reports gas for both forms", async function () {
      const o = opening(base, 5);
      const g1Only = await harness.verify.estimateGas(base.commitment, o.w, o.z, o.y);
      const g2Msm = await harness.verifyWithG2Msm.estimateGas(base.commitment, o.w, o.z, o.y);
      console.log(`    G1-only form : ${Number(g1Only).toLocaleString()} gas (eth_estimateGas, incl. 21,000 base)`);
      console.log(`    G2MSM form   : ${Number(g2Msm).toLocaleString()} gas`);
      expect(g1Only).to.be.lessThan(g2Msm);
    });
  });
});
